12	const appName = "caretrack"
13	
14	const helpText = `caretrack — 本地设备资产登记与维修工单闭环工具
15	
16	数据保存在本地目录，无外部服务依赖，仅支持单进程顺序调用。
17	
18	用法:
19	  caretrack <命令> [参数]
20	
21	命令:
22	  register   登记资产（企业资产编号、名称、位置）
23	  list       列出全部资产及当前状态
24	  detail     查看资产详情及其未关闭工单编号
25	  report     对资产报修，创建工单，资产转为“维修中”
26	  close      关闭工单并填写维修结果，设备恢复“可用”
27	  cancel     取消误报或不再需要维修的未关闭工单，设备恢复“可用”
28	  history    按资产查看维修履历（报修、关闭、取消事件）
29	  help       显示本帮助
30	
31	各命令参数:
32	  register --asset-id 编号 --name 名称 --location 位置 [--data-dir 目录]
33	  list                                                        [--data-dir 目录]
34	  detail   --asset-id 编号                                    [--data-dir 目录]
35	  report   --asset-id 编号 --description 故障描述 --request-id 请求标识
36	                                                              [--data-dir 目录]
37	  close    --ticket-id 工单编号 --repair-result 维修结果       [--data-dir 目录]
38	  cancel   --ticket-id 工单编号 --reason 取消理由              [--data-dir 目录]
39	  history  --asset-id 编号                                    [--data-dir 目录]
40	
41	通用参数:
42	  --data-dir 目录   本地数据目录，默认 ".caretrack"；不同目录数据互不影响，
43	                    目录不存在时会在首次成功写入时自动初始化
44	
45	业务规则:
46	  - 资产编号、名称、位置均不能为空；同一数据目录内资产编号唯一，新资产为“可用”。
47	  - 每项资产最多有一张未关闭工单；未知资产、空故障描述、资产已有未关闭工单时
48	    报修失败，不改变状态与履历。
49	  - --request-id 由调用方提供且非空，仅用于同一数据目录内的报修去重，不作为
50	    资产或工单编号：相同标识、资产、描述再次提交返回原工单及当前状态，不新增
51	    记录；同一标识搭配不同资产或描述将被拒绝；原工单关闭或取消后重放仍返回原工单，
52	    不重开旧单，也不影响新单。
53	  - 仅未关闭工单可关闭，维修结果不能为空；未知工单、重复关闭均失败。
54	  - 仅未关闭工单可取消，取消理由不能为空；取消后工单进入“已取消”终态，保存取消
55	    理由与时间，资产恢复“可用”，可再次报修。取消不代表维修完成，不填写维修结果，
56	    不删除工单、履历或请求绑定，工单编号不回退也不复用；已取消工单不能关闭或再次
57	    取消，已关闭工单也不能取消。
58	
59	无参数、--help、-h 显示本帮助；参数错误或业务失败以非零退出码结束并说明原因。
60	`
61	
62	type cmdOptions struct {
63		dataDir string
64	}
65	
66	func printHelp(w io.Writer) {
67		fmt.Fprint(w, helpText)
68	}
69	
70	func main() {
71		os.Exit(run(os.Args[1:], os.Stdout, os.Stderr))
72	}
73	
74	func run(args []string, stdout, stderr io.Writer) int {
75		if len(args) == 0 {
76			printHelp(stdout)
77			return 0
78		}
79		switch args[0] {
80		case "--help", "-h", "help":
81			if len(args) > 1 {
82				fmt.Fprintf(stderr, "%s: help 不接受额外参数\n", appName)
83				return 2
84			}
85			printHelp(stdout)
86			return 0
87		}
88	
89		var err error
90		switch args[0] {
91		case "register":
92			err = cmdRegister(args[1:], stdout)
93		case "list":
94			err = cmdList(args[1:], stdout)
95		case "detail":
96			err = cmdDetail(args[1:], stdout)
97		case "report":
98			err = cmdReport(args[1:], stdout)
99		case "close":
100			err = cmdClose(args[1:], stdout)
101		case "cancel":
102			err = cmdCancel(args[1:], stdout)
103		case "history":
104			err = cmdHistory(args[1:], stdout)
105		default:
106			fmt.Fprintf(stderr, "%s: 未知命令 %q，使用 --help 查看帮助\n", appName, args[0])
107			return 2
108		}
109		if err != nil {
110			if errors.Is(err, flag.ErrHelp) {
111				return 0
112			}
113			var ue *usageError
114			if errors.As(err, &ue) {
115				fmt.Fprintf(stderr, "%s: %s\n", appName, ue.Error())
116				return 2
117			}
118			fmt.Fprintf(stderr, "%s: %s\n", appName, friendlyErr(err.Error()))
119			return 1
120		}
121		return 0
122	}
123	
124	// friendlyErr 去掉内部哨兵错误（errNotFound/errConflict）的英文前缀。
125	func friendlyErr(msg string) string {
126		for _, p := range []string{"not found: ", "conflict: "} {
127			if strings.HasPrefix(msg, p) {
128				return msg[len(p):]
129			}
130		}
131		return msg
132	}
133	
134	type usageError struct{ msg string }
135	
136	func (e *usageError) Error() string { return e.msg }
137	
138	// newFlagSet 为子命令准备参数解析器：--help/-h 输出帮助并返回 flag.ErrHelp，
139	// 其余参数错误转成 *usageError（退出码 2）。
140	func newFlagSet(name string, opts *cmdOptions) *flag.FlagSet {
141		fs := flag.NewFlagSet(name, flag.ContinueOnError)
142		fs.SetOutput(os.Stdout)
143		fs.Usage = func() {
144			fmt.Fprintf(os.Stdout, "用法: caretrack %s [参数]\n\n", name)
145			fs.PrintDefaults()
146		}
147		fs.StringVar(&opts.dataDir, "data-dir", ".caretrack", "本地数据目录")
148		return fs
149	}
150	
151	func parseFlags(fs *flag.FlagSet, args []string) error {
152		if err := fs.Parse(args); err != nil {
153			if errors.Is(err, flag.ErrHelp) {
154				return err
155			}
156			return &usageError{msg: err.Error()}
157		}
158		if fs.NArg() > 0 {
159			return &usageError{msg: fmt.Sprintf("命令 %s 不接受位置参数: %v", fs.Name(), fs.Args())}
160		}
161		return nil
162	}
163	
164	func requireFlag(fs *flag.FlagSet, value, flagName string) error {
165		if value == "" {
166			return &usageError{msg: fmt.Sprintf("命令 %s 缺少必填参数 --%s", fs.Name(), flagName)}
167		}
168		return nil
169	}
170	
171	func cmdRegister(args []string, w io.Writer) error {
172		var opts cmdOptions
173		var id, name, location string
174		fs := newFlagSet("register", &opts)
175		fs.StringVar(&id, "asset-id", "", "企业资产编号（必填，同一数据目录内唯一）")
176		fs.StringVar(&name, "name", "", "资产名称（必填）")
177		fs.StringVar(&location, "location", "", "资产位置（必填）")
178		if err := parseFlags(fs, args); err != nil {
179			return err
180		}
181		if err := requireFlag(fs, id, "asset-id"); err != nil {
182			return err
183		}
184		if err := requireFlag(fs, name, "name"); err != nil {
185			return err
186		}
187		if err := requireFlag(fs, location, "location"); err != nil {
188			return err
189		}
190	
191		s, err := openStore(opts.dataDir)
192		if err != nil {
193			return err
194		}
195		asset, err := s.registerAsset(id, name, location)
196		if err != nil {
197			return err
198		}
199		if err := s.save(); err != nil {
200			return err
201		}
202		fmt.Fprintf(w, "已登记资产 %s\n", asset.ID)
203		fmt.Fprintf(w, "名称: %s\n", asset.Name)
204		fmt.Fprintf(w, "位置: %s\n", asset.Location)
205		fmt.Fprintf(w, "当前状态: %s\n", asset.Status)
206		return nil
207	}
208	
209	func cmdList(args []string, w io.Writer) error {
210		var opts cmdOptions
211		fs := newFlagSet("list", &opts)
212		if err := parseFlags(fs, args); err != nil {
213			return err
214		}
215		s, err := openStore(opts.dataDir)
216		if err != nil {
217			return err
218		}
219		assets := s.data.Assets
220		if len(assets) == 0 {
221			fmt.Fprintln(w, "没有记录。")
222			return nil
223		}
224		fmt.Fprintf(w, "共 %d 项资产:\n", len(assets))
225		for _, a := range assets {
226			fmt.Fprintf(w, "%s\t%s\t%s\t%s\n", a.ID, a.Name, a.Location, a.Status)
227		}
228		return nil
229	}
230	
231	func cmdDetail(args []string, w io.Writer) error {
232		var opts cmdOptions
233		var id string
234		fs := newFlagSet("detail", &opts)
235		fs.StringVar(&id, "asset-id", "", "企业资产编号（必填）")
236		if err := parseFlags(fs, args); err != nil {
237			return err
238		}
239		if err := requireFlag(fs, id, "asset-id"); err != nil {
240			return err
241		}
242		s, err := openStore(opts.dataDir)
243		if err != nil {
244			return err
245		}
246		asset := s.findAsset(id)
247		if asset == nil {
248			return fmt.Errorf("未知资产编号 %q", id)
249		}
250		openTicket := s.openTicketOf(asset.ID)
251		fmt.Fprintf(w, "资产编号: %s\n", asset.ID)
252		fmt.Fprintf(w, "名称: %s\n", asset.Name)
253		fmt.Fprintf(w, "位置: %s\n", asset.Location)
254		fmt.Fprintf(w, "当前状态: %s\n", asset.Status)
255		if openTicket == nil {
256			fmt.Fprintln(w, "未关闭工单: 无")
257		} else {
258			fmt.Fprintf(w, "未关闭工单: %s\n", openTicket.ID)
259		}
260		return nil
261	}
262	
263	func cmdReport(args []string, w io.Writer) error {
264		var opts cmdOptions
265		var assetID, description, requestID string
266		fs := newFlagSet("report", &opts)
267		fs.StringVar(&assetID, "asset-id", "", "企业资产编号（必填）")
268		fs.StringVar(&description, "description", "", "故障描述（必填）")
269		fs.StringVar(&requestID, "request-id", "", "调用方提供的非空请求标识，用于报修去重（必填）")
270		if err := parseFlags(fs, args); err != nil {
271			return err
272		}
273		if err := requireFlag(fs, assetID, "asset-id"); err != nil {
274			return err
275		}
276		if err := requireFlag(fs, description, "description"); err != nil {
277			return err
278		}
279		if err := requireFlag(fs, requestID, "request-id"); err != nil {
280			return err
281		}
282	
283		s, err := openStore(opts.dataDir)
284		if err != nil {
285			return err
286		}
287		ticket, replayed, err := s.report(assetID, description, requestID)
288		if err != nil {
289			return err
290		}
291		if !replayed {
292			if err := s.save(); err != nil {
293				return err
294			}
295			fmt.Fprintf(w, "工单编号: %s\n", ticket.ID)
296		} else {
297			fmt.Fprintf(w, "该请求标识已提交过，返回原工单，未重复创建。\n")
298			fmt.Fprintf(w, "工单编号: %s（既有工单）\n", ticket.ID)
299		}
300		fmt.Fprintf(w, "资产编号: %s\n", ticket.AssetID)
301		fmt.Fprintf(w, "工单状态: %s\n", ticket.Status)
302		return nil
303	}
304	
305	func cmdClose(args []string, w io.Writer) error {
306		var opts cmdOptions
307		var ticketID, result string
308		fs := newFlagSet("close", &opts)
309		fs.StringVar(&ticketID, "ticket-id", "", "要关闭的工单编号（必填）")
310		fs.StringVar(&result, "repair-result", "", "维修结果（必填）")
311		if err := parseFlags(fs, args); err != nil {
312			return err
313		}
314		if err := requireFlag(fs, ticketID, "ticket-id"); err != nil {
315			return err
316		}
317		if err := requireFlag(fs, result, "repair-result"); err != nil {
318			return err
319		}
320	
321		s, err := openStore(opts.dataDir)
322		if err != nil {
323			return err
324		}
325		ticket, asset, err := s.closeTicket(ticketID, result)
326		if err != nil {
327			return err
328		}
329		if err := s.save(); err != nil {
330			return err
331		}
332		fmt.Fprintf(w, "工单 %s 已关闭。\n", ticket.ID)
333		fmt.Fprintf(w, "资产 %s 当前状态: %s\n", asset.ID, asset.Status)
334		return nil
335	}
336	
337	func cmdCancel(args []string, w io.Writer) error {
338		var opts cmdOptions
339		var ticketID, reason string
340		fs := newFlagSet("cancel", &opts)
341		fs.StringVar(&ticketID, "ticket-id", "", "要取消的工单编号（必填）")
342		fs.StringVar(&reason, "reason", "", "取消理由（必填，非空）")
343		if err := parseFlags(fs, args); err != nil {
344			return err
345		}
346		if err := requireFlag(fs, ticketID, "ticket-id"); err != nil {
347			return err
348		}
349		if err := requireFlag(fs, reason, "reason"); err != nil {
350			return err
351		}
352	
353		s, err := openStore(opts.dataDir)
354		if err != nil {
355			return err
356		}
357		ticket, asset, err := s.cancelTicket(ticketID, reason)
358		if err != nil {
359			return err
360		}
361		if err := s.save(); err != nil {
362			return err
363		}
364		fmt.Fprintf(w, "工单 %s 已取消。\n", ticket.ID)
365		fmt.Fprintf(w, "工单状态: %s\n", ticket.Status)
366		fmt.Fprintf(w, "资产 %s 当前状态: %s\n", asset.ID, asset.Status)
367		return nil
368	}
369	
370	func cmdHistory(args []string, w io.Writer) error {
371		var opts cmdOptions
372		var id string
373		fs := newFlagSet("history", &opts)
374		fs.StringVar(&id, "asset-id", "", "企业资产编号（必填）")
375		if err := parseFlags(fs, args); err != nil {
376			return err
377		}
378		if err := requireFlag(fs, id, "asset-id"); err != nil {
379			return err
380		}
381		s, err := openStore(opts.dataDir)
382		if err != nil {
383			return err
384		}
385		if s.findAsset(id) == nil {
386			return fmt.Errorf("未知资产编号 %q", id)
387		}
388		events := s.eventsOf(id)
389		if len(events) == 0 {
390			fmt.Fprintf(w, "资产 %s 暂无维修履历。\n", id)
391			return nil
392		}
393		fmt.Fprintf(w, "资产 %s 维修履历（共 %d 条）:\n", id, len(events))
394		for _, e := range events {
395			fmt.Fprintf(w, "[%s] %s 工单 %s: %s\n",
396				e.Time.Format("2006-01-02T15:04:05Z07:00"), e.Kind, e.TicketID, e.Content)
397		}
398		return nil
399	}
