1	package main
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"math"
9		"os"
10		"path/filepath"
11		"sort"
12		"strconv"
13		"strings"
14		"time"
15	)
16	
17	// 资产状态、工单状态与履历类型。
18	const (
19		statusAvailable = "可用"
20		statusRepairing = "维修中"
21		ticketOpen      = "未关闭"
22		ticketClosed    = "已关闭"
23		ticketCancelled = "已取消"
24	
25		eventReport = "报修"
26		eventClose  = "关闭"
27		eventCancel = "取消"
28	
29		storeVersion = 1
30		dataFileName = "caretrack.json"
31	)
32	
33	var (
34		errNotFound = errors.New("not found")
35		errConflict = errors.New("conflict")
36	)
37	
38	// Asset 为登记的设备资产，ID 即企业资产编号。
39	type Asset struct {
40		ID       string `json:"id"`
41		Name     string `json:"name"`
42		Location string `json:"location"`
43		Status   string `json:"status"`
44	}
45	
46	// Ticket 为维修工单。
47	type Ticket struct {
48		ID           string `json:"id"`
49		AssetID      string `json:"asset_id"`
50		Description  string `json:"description"`
51		RequestID    string `json:"request_id"`
52		Status       string `json:"status"`
53		Result       string `json:"result,omitempty"`
54		CreatedAt    string `json:"created_at"`
55		ClosedAt     string `json:"closed_at,omitempty"`
56		CancelReason string `json:"cancel_reason,omitempty"`
57		CancelledAt  string `json:"cancelled_at,omitempty"`
58	}
59	
60	// Event 为履历条目（报修/关闭/取消），Seq 决定操作发生顺序。
61	type Event struct {
62		Seq      int       `json:"-"`
63		AssetID  string    `json:"-"`
64		TicketID string    `json:"-"`
65		Kind     string    `json:"-"`
66		Content  string    `json:"-"`
67		Time     time.Time `json:"-"`
68	}
69	
70	// eventJSON 与 Event 对应，时间以 RFC3339 文本持久化。
71	type eventJSON struct {
72		Seq      int    `json:"seq"`
73		AssetID  string `json:"asset_id"`
74		TicketID string `json:"ticket_id"`
75		Kind     string `json:"kind"`
76		Content  string `json:"content"`
77		Time     string `json:"time"`
78	}
79	
80	func (e Event) toJSON() eventJSON {
81		return eventJSON{
82			Seq: e.Seq, AssetID: e.AssetID, TicketID: e.TicketID,
83			Kind: e.Kind, Content: e.Content, Time: e.Time.Format(time.RFC3339),
84		}
85	}
86	
87	func (e eventJSON) toEvent() (Event, error) {
88		t, err := time.Parse(time.RFC3339, e.Time)
89		if err != nil {
90			return Event{}, fmt.Errorf("履历时间格式无效 %q: %w", e.Time, err)
91		}
92		return Event{
93			Seq: e.Seq, AssetID: e.AssetID, TicketID: e.TicketID,
94			Kind: e.Kind, Content: e.Content, Time: t,
95		}, nil
96	}
97	
98	// requestBinding 记录请求标识与具体报修的绑定，用于去重与冲突拒绝；
99	// 它既不是资产编号也不是工单编号。
100	type requestBinding struct {
101		RequestID   string `json:"request_id"`
102		AssetID     string `json:"asset_id"`
103		Description string `json:"description"`
104		TicketID    string `json:"ticket_id"`
105	}
106	
107	// storeData 是一次成功写操作共同生效的完整业务数据。
108	type storeData struct {
109		Version       int              `json:"version"`
110		Assets        []*Asset         `json:"assets"`
111		Tickets       []*Ticket        `json:"tickets"`
112		Events        []Event          `json:"-"`
113		EventsJSON    []eventJSON      `json:"events"`
114		Requests      []requestBinding `json:"requests"`
115		NextTicketSeq int              `json:"next_ticket_seq"`
116	}
117	
118	type store struct {
119		dir  string
120		data *storeData
121		now  func() time.Time
122	}
123	
124	func newStoreData() *storeData {
125		return &storeData{
126			Version:       storeVersion,
127			Assets:        []*Asset{},
128			Tickets:       []*Ticket{},
129			Events:        []Event{},
130			EventsJSON:    []eventJSON{},
131			Requests:      []requestBinding{},
132			NextTicketSeq: 1,
133		}
134	}
135	
136	// openStore 打开数据目录：目录/文件不存在时视为空库（首次保存时初始化）；
137	// 已有文件为空或无法解析时报告错误并保留原文件，绝不当空库覆盖。
138	func openStore(dir string) (*store, error) {
139		path := filepath.Join(dir, dataFileName)
140		raw, err := os.ReadFile(path)
141		if err != nil {
142			if errors.Is(err, os.ErrNotExist) {
143				return &store{dir: dir, data: newStoreData(), now: time.Now}, nil
144			}
145			return nil, fmt.Errorf("读取数据文件失败: %w", err)
146		}
147		if len(bytes.TrimSpace(raw)) == 0 {
148			return nil, fmt.Errorf("数据文件 %s 已损坏：文件为空（原文件已保留，未做任何修改）", path)
149		}
150		var d storeData
151		if err := json.Unmarshal(raw, &d); err != nil {
152			return nil, fmt.Errorf("数据文件 %s 已损坏：%w（原文件已保留，未做任何修改）", path, err)
153		}
154		if d.EventsJSON != nil {
155			d.Events = make([]Event, len(d.EventsJSON))
156			for i, ej := range d.EventsJSON {
157				ev, err := ej.toEvent()
158				if err != nil {
159					return nil, fmt.Errorf("数据文件 %s 已损坏：%w（原文件已保留，未做任何修改）", path, err)
160				}
161				d.Events[i] = ev
162			}
163		}
164		if err := validateData(&d); err != nil {
165			return nil, fmt.Errorf("数据文件 %s 内容相互矛盾：%w（原文件已保留，未做任何修改）", path, err)
166		}
167		return &store{dir: dir, data: &d, now: time.Now}, nil
168	}
169	
170	// parseTicketSeq 解析 T 加补零正整数序号形式的工单编号，返回序号。
171	// 编号必须与 fmt.Sprintf("T%04d", n)（n ≥ 1）完全一致，否则视为非法。
172	func parseTicketSeq(id string) (int, bool) {
173		if !strings.HasPrefix(id, "T") {
174			return 0, false
175		}
176		n, err := strconv.Atoi(id[1:])
177		if err != nil || n < 1 {
178			return 0, false
179		}
180		if fmt.Sprintf("T%04d", n) != id {
181			return 0, false
182		}
183		return n, true
184	}
185	
186	// validateData 校验整份业务数据的内部一致性。任何矛盾都会返回指明问题类别
187	// （计数器/请求绑定/状态/履历）的错误；调用方必须拒绝查询与写入并保留原文件。
188	// 不做任何修复：不补字段、不重编号、不删除记录。
189	func validateData(d *storeData) error {
190		if d.Version != storeVersion {
191			return fmt.Errorf("不支持的数据版本 %d", d.Version)
192		}
193		if d.Assets == nil || d.Tickets == nil || d.Requests == nil || d.EventsJSON == nil || d.Events == nil {
194			return errors.New("缺少必要的数据段")
195		}
196		assets := map[string]*Asset{}
197		for _, a := range d.Assets {
198			if a == nil || a.ID == "" || a.Name == "" || a.Location == "" {
199				return errors.New("数据矛盾：存在字段不完整的资产记录")
200			}
201			if a.Status != statusAvailable && a.Status != statusRepairing {
202				return fmt.Errorf("状态矛盾：资产 %s 状态无效 %q", a.ID, a.Status)
203			}
204			if assets[a.ID] != nil {
205				return fmt.Errorf("数据矛盾：资产编号 %s 重复", a.ID)
206			}
207			assets[a.ID] = a
208		}
209		tickets := map[string]*Ticket{}
210		maxTicketSeq := 0
211		for _, t := range d.Tickets {
212			if t == nil || t.ID == "" || t.AssetID == "" || t.RequestID == "" || t.Description == "" || t.CreatedAt == "" {
213				return errors.New("数据矛盾：存在字段不完整的工单记录（工单描述不能为空）")
214			}
215			n, ok := parseTicketSeq(t.ID)
216			if !ok {
217				return fmt.Errorf("计数器矛盾：工单编号 %q 不是 T 加补零正整数序号的形式", t.ID)
218			}
219			if n > maxTicketSeq {
220				maxTicketSeq = n
221			}
222			if t.Status != ticketOpen && t.Status != ticketClosed && t.Status != ticketCancelled {
223				return fmt.Errorf("状态矛盾：工单 %s 状态无效 %q", t.ID, t.Status)
224			}
225			if assets[t.AssetID] == nil {
226				return fmt.Errorf("数据矛盾：工单 %s 引用了不存在的资产 %s", t.ID, t.AssetID)
227			}
228			if t.Status == ticketClosed && (t.Result == "" || t.ClosedAt == "") {
229				return fmt.Errorf("状态矛盾：已关闭工单 %s 缺少维修结果或关闭时间", t.ID)
230			}
231			if t.Status == ticketCancelled && (t.CancelReason == "" || t.CancelledAt == "") {
232				return fmt.Errorf("状态矛盾：已取消工单 %s 缺少取消理由或取消时间", t.ID)
233			}
234			if t.Status != ticketClosed && (t.Result != "" || t.ClosedAt != "") {
235				return fmt.Errorf("状态矛盾：非已关闭工单 %s 不应带有维修结果或关闭时间", t.ID)
236			}
237			if t.Status != ticketCancelled && (t.CancelReason != "" || t.CancelledAt != "") {
238				return fmt.Errorf("状态矛盾：非已取消工单 %s 不应带有取消理由或取消时间", t.ID)
239			}
240			if tickets[t.ID] != nil {
241				return fmt.Errorf("数据矛盾：工单编号 %s 重复", t.ID)
242			}
243			tickets[t.ID] = t
244		}
245		// 下一工单序号必须为正并大于全部已用序号（允许有间隔）。
246		if d.NextTicketSeq < 1 || d.NextTicketSeq <= maxTicketSeq {
247			return fmt.Errorf("计数器矛盾：下一工单序号 %d 必须为正并大于全部已用序号（当前最大 %d）",
248				d.NextTicketSeq, maxTicketSeq)
249		}
250		// 请求绑定：每张工单恰有一条绑定，且请求标识、资产、描述、工单编号完全一致。
251		boundReq := map[string]bool{}
252		boundTicket := map[string]bool{}
253		for _, r := range d.Requests {
254			if r.RequestID == "" || r.AssetID == "" || r.Description == "" || r.TicketID == "" {
255				return errors.New("请求绑定矛盾：存在字段不完整的请求绑定记录")
256			}
257			if boundReq[r.RequestID] {
258				return fmt.Errorf("请求绑定矛盾：请求标识 %s 被绑定多次", r.RequestID)
259			}
260			boundReq[r.RequestID] = true
261			t := tickets[r.TicketID]
262			if t == nil {
263				return fmt.Errorf("请求绑定矛盾：请求标识 %s 绑定的工单 %s 不存在", r.RequestID, r.TicketID)
264			}
265			if t.RequestID != r.RequestID {
266				return fmt.Errorf("请求绑定矛盾：工单 %s 的请求标识为 %s，绑定记录却来自请求 %s",
267					r.TicketID, t.RequestID, r.RequestID)
268			}
269			if r.AssetID != t.AssetID || r.Description != t.Description {
270				return fmt.Errorf("请求绑定矛盾：请求标识 %s 绑定的资产编号或故障描述与工单 %s 不一致",
271					r.RequestID, t.ID)
272			}
273			boundTicket[r.TicketID] = true
274		}
275		for _, t := range d.Tickets {
276			if !boundTicket[t.ID] {
277				return fmt.Errorf("请求绑定矛盾：工单 %s 缺少对应的报修请求绑定", t.ID)
278			}
279		}
280		// 状态：每项资产最多一张未关闭工单，有则“维修中”，无则“可用”。
281		openCount := map[string]int{}
282		for _, t := range d.Tickets {
283			if t.Status == ticketOpen {
284				openCount[t.AssetID]++
285			}
286		}
287		for _, a := range d.Assets {
288			c := openCount[a.ID]
289			if c > 1 {
290				return fmt.Errorf("状态矛盾：资产 %s 有 %d 张未关闭工单，最多允许一张", a.ID, c)
291			}
292			want := statusAvailable
293			if c == 1 {
294				want = statusRepairing
295			}
296			if a.Status != want {
297				return fmt.Errorf("状态矛盾：资产 %s 有 %d 张未关闭工单，状态应为 %s，实际为 %s",
298					a.ID, c, want, a.Status)
299			}
300		}
301		// 履历：序号全库唯一且为正整数；归属、内容与工单一致。
302		seenSeq := map[int]bool{}
303		reportSeq := map[string]int{}
304		closeSeq := map[string]int{}
305		cancelSeq := map[string]int{}
306		reportCount := map[string]int{}
307		closeCount := map[string]int{}
308		cancelCount := map[string]int{}
309		for i := range d.Events {
310			e := &d.Events[i]
311			if e.Seq < 1 {
312				return fmt.Errorf("履历矛盾：履历序号 %d 不是正整数", e.Seq)
313			}
314			if seenSeq[e.Seq] {
315				return fmt.Errorf("履历矛盾：履历序号 %d 重复", e.Seq)
316			}
317			seenSeq[e.Seq] = true
318			if e.AssetID == "" || e.TicketID == "" || e.Kind == "" || e.Content == "" {
319				return errors.New("履历矛盾：存在字段不完整的履历记录")
320			}
321			t := tickets[e.TicketID]
322			if t == nil || assets[e.AssetID] == nil {
323				return fmt.Errorf("履历矛盾：履历序号 %d 引用了不存在的资产或工单", e.Seq)
324			}
325			if e.AssetID != t.AssetID {
326				return fmt.Errorf("履历矛盾：履历序号 %d 的资产 %s 与工单 %s 归属的资产 %s 不一致",
327					e.Seq, e.AssetID, t.ID, t.AssetID)
328			}
329			switch e.Kind {
330			case eventReport:
331				if e.Content != t.Description {
332					return fmt.Errorf("履历矛盾：工单 %s 的报修履历内容与故障描述不一致", t.ID)
333				}
334				reportCount[t.ID]++
335				reportSeq[t.ID] = e.Seq
336			case eventClose:
337				if e.Content != t.Result {
338					return fmt.Errorf("履历矛盾：工单 %s 的关闭履历内容与维修结果不一致", t.ID)
339				}
340				closeCount[t.ID]++
341				closeSeq[t.ID] = e.Seq
342			case eventCancel:
343				if e.Content != t.CancelReason {
344					return fmt.Errorf("履历矛盾：工单 %s 的取消履历内容与取消理由不一致", t.ID)
345				}
346				cancelCount[t.ID]++
347				cancelSeq[t.ID] = e.Seq
348			default:
349				return fmt.Errorf("履历矛盾：履历序号 %d 的事件类型无效 %q", e.Seq, e.Kind)
350			}
351		}
352		for _, t := range d.Tickets {
353			if reportCount[t.ID] != 1 {
354				return fmt.Errorf("履历矛盾：工单 %s 应有恰一条报修履历，实际 %d 条", t.ID, reportCount[t.ID])
355			}
356			if t.Status == ticketClosed {
357				if closeCount[t.ID] != 1 {
358					return fmt.Errorf("履历矛盾：已关闭工单 %s 应有恰一条关闭履历，实际 %d 条", t.ID, closeCount[t.ID])
359				}
360				if closeSeq[t.ID] <= reportSeq[t.ID] {
361					return fmt.Errorf("履历矛盾：工单 %s 的关闭履历（序号 %d）不在报修履历（序号 %d）之后",
362						t.ID, closeSeq[t.ID], reportSeq[t.ID])
363				}
364			} else if closeCount[t.ID] != 0 {
365				return fmt.Errorf("履历矛盾：非已关闭工单 %s 不得有关闭履历", t.ID)
366			}
367			if t.Status == ticketCancelled {
368				if cancelCount[t.ID] != 1 {
369					return fmt.Errorf("履历矛盾：已取消工单 %s 应有恰一条取消履历，实际 %d 条", t.ID, cancelCount[t.ID])
370				}
371				if cancelSeq[t.ID] <= reportSeq[t.ID] {
372					return fmt.Errorf("履历矛盾：工单 %s 的取消履历（序号 %d）不在报修履历（序号 %d）之后",
373						t.ID, cancelSeq[t.ID], reportSeq[t.ID])
374				}
375			} else if cancelCount[t.ID] != 0 {
376				return fmt.Errorf("履历矛盾：非已取消工单 %s 不得有取消履历", t.ID)
377			}
378		}
379		// 按履历序号推进，重放得到的工单与资产状态须与保存的状态相符；
380		// 同一资产的上一张工单必须先关闭或取消才可产生下一张报修。
381		sorted := make([]Event, len(d.Events))
382		copy(sorted, d.Events)
383		sort.SliceStable(sorted, func(i, j int) bool { return sorted[i].Seq < sorted[j].Seq })
384		derivedTicket := map[string]string{}
385		derivedOpen := map[string]string{}
386		for _, e := range sorted {
387			switch e.Kind {
388			case eventReport:
389				if derivedTicket[e.TicketID] != "" {
390					return fmt.Errorf("履历矛盾：工单 %s 被重复报修", e.TicketID)
391				}
392				if prev := derivedOpen[e.AssetID]; prev != "" {
393					return fmt.Errorf("履历矛盾：资产 %s 的上一张工单 %s 尚未结束就产生了工单 %s 的报修",
394						e.AssetID, prev, e.TicketID)
395				}
396				derivedTicket[e.TicketID] = ticketOpen
397				derivedOpen[e.AssetID] = e.TicketID
398			case eventClose:
399				if derivedTicket[e.TicketID] != ticketOpen {
400					return fmt.Errorf("履历矛盾：工单 %s 在未处于未关闭状态时出现关闭履历", e.TicketID)
401				}
402				derivedTicket[e.TicketID] = ticketClosed
403				delete(derivedOpen, e.AssetID)
404			case eventCancel:
405				if derivedTicket[e.TicketID] != ticketOpen {
406					return fmt.Errorf("履历矛盾：工单 %s 在未处于未关闭状态时出现取消履历", e.TicketID)
407				}
408				derivedTicket[e.TicketID] = ticketCancelled
409				delete(derivedOpen, e.AssetID)
410			}
411		}
412		for _, t := range d.Tickets {
413			if derivedTicket[t.ID] != t.Status {
414				return fmt.Errorf("状态矛盾：按履历推进得到工单 %s 状态为 %s，与保存的 %s 不符",
415					t.ID, derivedTicket[t.ID], t.Status)
416			}
417		}
418		for _, a := range d.Assets {
419			want := statusAvailable
420			if derivedOpen[a.ID] != "" {
421				want = statusRepairing
422			}
423			if a.Status != want {
424				return fmt.Errorf("状态矛盾：按履历推进得到资产 %s 状态为 %s，与保存的 %s 不符",
425					a.ID, want, a.Status)
426			}
427		}
428		return nil
429	}
430	
431	// save 将全部业务数据一次性原子写入：先写同目录临时文件，fsync 后 rename
432	// 覆盖正式文件。写入前先校验待提交数据的一致性；校验或读写失败时原文件
433	// 保持不变，不留下部分业务变化。
434	func (s *store) save() error {
435		s.data.EventsJSON = make([]eventJSON, len(s.data.Events))
436		for i, e := range s.data.Events {
437			s.data.EventsJSON[i] = e.toJSON()
438		}
439		if err := validateData(s.data); err != nil {
440			return fmt.Errorf("待保存数据未通过一致性检查：%w（未写入任何数据）", err)
441		}
442		var buf bytes.Buffer
443		enc := json.NewEncoder(&buf)
444		enc.SetIndent("", "  ")
445		if err := enc.Encode(s.data); err != nil {
446			return fmt.Errorf("编码数据失败: %w", err)
447		}
448		if err := os.MkdirAll(s.dir, 0o755); err != nil {
449			return fmt.Errorf("创建数据目录失败: %w", err)
450		}
451		path := filepath.Join(s.dir, dataFileName)
452		tmp, err := os.CreateTemp(s.dir, ".caretrack-*.tmp")
453		if err != nil {
454			return fmt.Errorf("创建临时数据文件失败: %w", err)
455		}
456		tmpName := tmp.Name()
457		abort := func(err error) error {
458			_ = tmp.Close()
459			_ = os.Remove(tmpName)
460			return err
461		}
462		if _, err := tmp.Write(buf.Bytes()); err != nil {
463			abort(nil)
464			return fmt.Errorf("写入数据失败: %w", err)
465		}
466		if err := tmp.Sync(); err != nil {
467			abort(nil)
468			return fmt.Errorf("写入数据失败: %w", err)
469		}
470		if err := tmp.Close(); err != nil {
471			_ = os.Remove(tmpName)
472			return fmt.Errorf("写入数据失败: %w", err)
473		}
474		if err := os.Rename(tmpName, path); err != nil {
475			_ = os.Remove(tmpName)
476			return fmt.Errorf("保存数据失败: %w", err)
477		}
478		return nil
479	}
480	
481	func (s *store) findAsset(id string) *Asset {
482		for _, a := range s.data.Assets {
483			if a.ID == id {
484				return a
485			}
486		}
487		return nil
488	}
489	
490	func (s *store) findTicket(id string) *Ticket {
491		for _, t := range s.data.Tickets {
492			if t.ID == id {
493				return t
494			}
495		}
496		return nil
497	}
498	
499	func (s *store) findRequest(requestID string) *requestBinding {
500		for i := range s.data.Requests {
501			if s.data.Requests[i].RequestID == requestID {
502				return &s.data.Requests[i]
503			}
504		}
505		return nil
506	}
507	
508	func (s *store) openTicketOf(assetID string) *Ticket {
509		for _, t := range s.data.Tickets {
510			if t.AssetID == assetID && t.Status == ticketOpen {
511				return t
512			}
513		}
514		return nil
515	}
516	
517	func (s *store) eventsOf(assetID string) []Event {
518		out := make([]Event, 0)
519		for _, e := range s.data.Events {
520			if e.AssetID == assetID {
521				out = append(out, e)
522			}
523		}
524		sort.SliceStable(out, func(i, j int) bool { return out[i].Seq < out[j].Seq })
525		return out
526	}
527	
528	// nextEventSeq 返回下一条履历应使用的全库唯一正整数序号；计数器耗尽时报错。
529	func (s *store) nextEventSeq() (int, error) {
530		maxSeq := 0
531		for _, e := range s.data.Events {
532			if e.Seq > maxSeq {
533				maxSeq = e.Seq
534			}
535		}
536		if maxSeq == math.MaxInt {
537			return 0, fmt.Errorf("%w: 履历序号计数器已耗尽，无法追加履历", errConflict)
538		}
539		return maxSeq + 1, nil
540	}
541	
542	// appendEvent 以给定序号追加履历。调用方须先通过 nextEventSeq 取得序号，
543	// 确保任何失败路径都不会在部分变更后才报错。
544	func (s *store) appendEvent(seq int, assetID, ticketID, kind, content string) {
545		s.data.Events = append(s.data.Events, Event{
546			Seq:      seq,
547			AssetID:  assetID,
548			TicketID: ticketID,
549			Kind:     kind,
550			Content:  content,
551			Time:     s.now(),
552		})
553	}
554	
555	func (s *store) registerAsset(id, name, location string) (*Asset, error) {
556		if s.findAsset(id) != nil {
557			return nil, fmt.Errorf("%w: 资产编号 %q 已存在", errConflict, id)
558		}
559		a := &Asset{ID: id, Name: name, Location: location, Status: statusAvailable}
560		s.data.Assets = append(s.data.Assets, a)
561		return a, nil
562	}
563	
564	// report 创建报修工单。返回 (工单, 是否为去重重放, 错误)。
565	// 所有失败路径都不修改任何业务数据，也不会绑定新的请求标识。
566	func (s *store) report(assetID, description, requestID string) (*Ticket, bool, error) {
567		// 已有绑定：相同资产+描述 => 返回原工单（无论其是否已关闭、是否已有新工单）；
568		// 资产或描述不同 => 拒绝。
569		if r := s.findRequest(requestID); r != nil {
570			if r.AssetID != assetID || r.Description != description {
571				return nil, false, fmt.Errorf(
572					"%w: 请求标识 %q 已用于资产 %q 的另一笔报修，不能搭配不同的资产编号或故障描述",
573					errConflict, requestID, r.AssetID)
574			}
575			t := s.findTicket(r.TicketID)
576			if t == nil {
577				return nil, false, fmt.Errorf("数据内部错误：请求标识 %q 绑定的工单不存在", requestID)
578			}
579			return t, true, nil
580		}
581	
582		asset := s.findAsset(assetID)
583		if asset == nil {
584			return nil, false, fmt.Errorf("%w: 未知资产编号 %q", errNotFound, assetID)
585		}
586		if t := s.openTicketOf(assetID); t != nil {
587			return nil, false, fmt.Errorf("%w: 资产 %s 已有未关闭工单 %s", errConflict, assetID, t.ID)
588		}
589		// 先确认编号与履历计数器都能推进，再修改任何业务数据：
590		// 编号耗尽时拒绝新报修，不消耗编号，也不绑定请求标识。
591		seq := s.data.NextTicketSeq
592		if seq < 1 || seq == math.MaxInt {
593			return nil, false, fmt.Errorf("%w: 工单编号计数器已耗尽，无法分配新工单编号", errConflict)
594		}
595		eventSeq, err := s.nextEventSeq()
596		if err != nil {
597			return nil, false, err
598		}
599		t := &Ticket{
600			ID:          fmt.Sprintf("T%04d", seq),
601			AssetID:     assetID,
602			Description: description,
603			RequestID:   requestID,
604			Status:      ticketOpen,
605			CreatedAt:   s.now().Format(time.RFC3339),
606		}
607		s.data.NextTicketSeq = seq + 1
608		s.data.Tickets = append(s.data.Tickets, t)
609		s.data.Requests = append(s.data.Requests, requestBinding{
610			RequestID:   requestID,
611			AssetID:     assetID,
612			Description: description,
613			TicketID:    t.ID,
614		})
615		asset.Status = statusRepairing
616		s.appendEvent(eventSeq, assetID, t.ID, eventReport, description)
617		return t, false, nil
618	}
619	
620	// closeTicket 关闭未关闭工单并把资产恢复为可用。
621	// 失败路径不修改任何业务数据。
622	func (s *store) closeTicket(ticketID, result string) (*Ticket, *Asset, error) {
623		t := s.findTicket(ticketID)
624		if t == nil {
625			return nil, nil, fmt.Errorf("%w: 未知工单编号 %q", errNotFound, ticketID)
626		}
627		if t.Status == ticketCancelled {
628			return nil, nil, fmt.Errorf("%w: 工单 %s 已取消，不能关闭", errConflict, ticketID)
629		}
630		if t.Status != ticketOpen {
631			return nil, nil, fmt.Errorf("%w: 工单 %s 已关闭，不能重复关闭", errConflict, ticketID)
632		}
633		asset := s.findAsset(t.AssetID)
634		if asset == nil {
635			return nil, nil, fmt.Errorf("数据内部错误：工单 %s 引用的资产不存在", ticketID)
636		}
637		eventSeq, err := s.nextEventSeq()
638		if err != nil {
639			return nil, nil, err
640		}
641		t.Status = ticketClosed
642		t.Result = result
643		t.ClosedAt = s.now().Format(time.RFC3339)
644		asset.Status = statusAvailable
645		s.appendEvent(eventSeq, asset.ID, t.ID, eventClose, result)
646		return t, asset, nil
647	}
648	
649	// cancelTicket 取消未关闭工单并把资产恢复为可用。取消是终态，但不代表维修完成：
650	// 不填写维修结果，不删除工单、履历或请求绑定，工单编号不回退也不复用。
651	// 失败路径不修改任何业务数据。
652	func (s *store) cancelTicket(ticketID, reason string) (*Ticket, *Asset, error) {
653		t := s.findTicket(ticketID)
654		if t == nil {
655			return nil, nil, fmt.Errorf("%w: 未知工单编号 %q", errNotFound, ticketID)
656		}
657		if t.Status == ticketCancelled {
658			return nil, nil, fmt.Errorf("%w: 工单 %s 已取消，不能再次取消", errConflict, ticketID)
659		}
660		if t.Status == ticketClosed {
661			return nil, nil, fmt.Errorf("%w: 工单 %s 已关闭，不能取消", errConflict, ticketID)
662		}
663		asset := s.findAsset(t.AssetID)
664		if asset == nil {
665			return nil, nil, fmt.Errorf("数据内部错误：工单 %s 引用的资产不存在", ticketID)
666		}
667		eventSeq, err := s.nextEventSeq()
668		if err != nil {
669			return nil, nil, err
670		}
671		t.Status = ticketCancelled
672		t.CancelReason = reason
673		t.CancelledAt = s.now().Format(time.RFC3339)
674		asset.Status = statusAvailable
675		s.appendEvent(eventSeq, asset.ID, t.ID, eventCancel, reason)
676		return t, asset, nil
677	}
