		t.Fatal(err)
	}
	if err := s.save(); err != nil {
		t.Fatal(err)
	}
	path := filepath.Join(s.dir, dataFileName)
	rawBefore, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
